select q.title, q.time_limit_minutes, (select count(*) from public.quiz_questions x where x.quiz_id = q.id) as items, (select sum(n.marks) from public.quiz_questions x join public.questions n on n.id = x.question_id where x.quiz_id = q.id) as marks, (select count(*) from public.quiz_classes c where c.quiz_id = q.id) as classes from public.quizzes q where q.id in ('ac86e4ed-9b42-507a-ba63-d61317aa0e6e', '897dbdca-e916-58dd-8580-081bacf9ac49', 'ed84a922-18c8-51e0-b321-d276580dbbf6', 'e3f94c49-027c-58af-8b81-8747063f431b') order by q.title;
