insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('b8cf2d8e-f906-5e95-878f-3d78d1e0711a', 'A vaccine contains dead or weakened pathogens or their antigens [1]; lymphocytes make antibodies against them [1]; memory cells remain and make antibodies quickly if the real pathogen enters [1].', 'A vaccine contains dead or weakened pathogens or their antigens [1]; lymphocytes make antibodies against them [1]; memory cells remain and make antibodies quickly if the real pathogen enters [1].', '[{"text": "A vaccine contains dead or weakened pathogens or their antigens", "any": ["dead", "weakened", "harmless", "antigen"], "all": [], "marks": 1}, {"text": "Lymphocytes make antibodies against them", "any": ["antibod", "lymphocyte"], "all": [], "marks": 1}, {"text": "Memory cells remain and make antibodies quickly if the real pathogen enters", "any": ["memory"], "all": [], "marks": 1}]'::jsonb, 'A vaccine contains dead or weakened pathogens or their antigens [1]; lymphocytes make antibodies against them [1]; memory cells remain and make antibodies quickly if the real pathogen enters [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
