insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('c26036c8-8ca1-55c4-817f-d43f10b99ac4', 'Glucose + oxygen [1] → carbon dioxide + water [1]; C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O [1].', 'Glucose + oxygen [1] → carbon dioxide + water [1]; C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O [1].', '[{"text": "Glucose + oxygen", "any": ["glucose oxygen", "glucose and oxygen"], "all": [], "marks": 1}, {"text": "→ carbon dioxide + water", "any": ["carbon dioxide water", "carbon dioxide and water"], "all": [], "marks": 1}, {"text": "C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O", "any": ["6co2", "6h2o", "6o2"], "all": [], "marks": 1}]'::jsonb, 'Glucose + oxygen [1] → carbon dioxide + water [1]; C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
