insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('d657b828-bc2d-5bf3-907f-38a6001646fa', 'ATP (adenosine triphosphate) is made using energy released in respiration [1]; it is broken down to release energy where cells need it, e.g. muscle contraction [1].', 'ATP (adenosine triphosphate) is made using energy released in respiration [1]; it is broken down to release energy where cells need it, e.g. muscle contraction [1].', '[{"text": "ATP (adenosine triphosphate) is made using energy released in respiration", "any": ["adenosine triphosphate", "energy currency", "made in respiration", "respiration"], "all": [], "marks": 1}, {"text": "It is broken down to release energy where cells need it, e.g. muscle contraction", "any": ["release", "broken down", "where needed", "muscle", "active transport"], "all": [], "marks": 1}]'::jsonb, 'ATP (adenosine triphosphate) is made using energy released in respiration [1]; it is broken down to release energy where cells need it, e.g. muscle contraction [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
