insert into public.quizzes (id, topic_id, title, instructions, time_limit_minutes, max_attempts, published, show_results, category, feedback_mode, created_by, subject) values ('897dbdca-e916-58dd-8580-081bacf9ac49', (select id from public.topics where id = '074d8b95-40b8-583a-9b76-9f324e19c12a'), 'Grade 9 · Biology · Digestion, enzymes, circulation and respiration · Criterion B test: Inquiring and designing', 'MYP 4 (Grade 9) Biology end-of-unit test. Statement of inquiry: evidence of healthy wellbeing is a consequence of the proper functioning of systems. Section 1: Criterion B: Inquiring and designing. Answer every question, using the command terms. Written answers are marked against the mark scheme; your teacher checks every mark. 19 marks, 40 minutes.', 40, 1, true, true, 'exam', 'hybrid', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e', 'Biology') on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, time_limit_minutes = excluded.time_limit_minutes, category = 'exam', subject = excluded.subject, topic_id = excluded.topic_id;
insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('603a3ec6-3252-5f05-ba74-fb11a85b67aa', (select id from public.topics where id = '074d8b95-40b8-583a-9b76-9f324e19c12a'), 'short', 'A student wants to investigate how temperature affects the rate at which amylase digests starch. Write a focused research question.', '[]'::jsonb, 2, 'Criterion B: Inquiring and designing', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('603a3ec6-3252-5f05-ba74-fb11a85b67aa', 'How does the temperature (20, 30, 40, 50, 60 °C) affect [1] the time taken for amylase to digest starch? [1]', 'How does the temperature (20, 30, 40, 50, 60 °C) affect [1] the time taken for amylase to digest starch? [1]', '[{"text": "How does the temperature (20, 30, 40, 50, 60 °C) affect", "any": ["how does", "what is the effect", "effect of"], "all": [], "marks": 1}, {"text": "The time taken for amylase to digest starch?", "any": ["temperature", "amylase", "starch", "rate", "time"], "all": [], "marks": 1}]'::jsonb, 'How does the temperature (20, 30, 40, 50, 60 °C) affect [1] the time taken for amylase to digest starch? [1]') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
