insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('f12d65c7-8e42-58b2-ac46-7c7dfd485d2e', (select id from public.topics where id = '074d8b95-40b8-583a-9b76-9f324e19c12a'), 'short', 'Write a hypothesis for this investigation and explain it using scientific reasoning.', '[]'::jsonb, 3, 'Criterion B: Inquiring and designing', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('f12d65c7-8e42-58b2-ac46-7c7dfd485d2e', 'If the temperature increases up to about 40 °C, the starch will be digested faster, then slower above it [1]; because about 40 °C is close to the optimum of human amylase [1]; molecules collide more at higher temperatures, but above the optimum the active site denatures [1].', 'If the temperature increases up to about 40 °C, the starch will be digested faster, then slower above it [1]; because about 40 °C is close to the optimum of human amylase [1]; molecules collide more at higher temperatures, but above the optimum the active site denatures [1].', '[{"text": "If the temperature increases up to about 40 °C, the starch will be digested faster, then slower above it", "any": ["if", "increase", "up to", "fastest"], "all": [], "marks": 1}, {"text": "Because about 40 °C is close to the optimum of human amylase", "any": ["optimum", "37", "40"], "all": [], "marks": 1}, {"text": "Molecules collide more at higher temperatures, but above the optimum the active site denatures", "any": ["denatur", "active site", "kinetic", "collisions"], "all": [], "marks": 1}]'::jsonb, 'If the temperature increases up to about 40 °C, the starch will be digested faster, then slower above it [1]; because about 40 °C is close to the optimum of human amylase [1]; molecules collide more at higher temperatures, but above the optimum the active site denatures [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
