insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('0e16fa33-0b80-5fe7-a701-358d828ee162', 'Independent: temperature [1]; dependent: the time until the starch is digested (iodine stays orange-brown) [1]; controls: the volume of starch and amylase [1], the concentration of starch and amylase [1], and the pH (using a buffer) [1].', 'Independent: temperature [1]; dependent: the time until the starch is digested (iodine stays orange-brown) [1]; controls: the volume of starch and amylase [1], the concentration of starch and amylase [1], and the pH (using a buffer) [1].', '[{"text": "Independent: temperature", "any": ["temperature"], "all": [], "marks": 1}, {"text": "Dependent: the time until the starch is digested (iodine stays orange-brown)", "any": ["time", "rate", "iodine"], "all": [], "marks": 1}, {"text": "Controls: the volume of starch and amylase", "any": ["volume"], "all": [], "marks": 1}, {"text": "The concentration of starch and amylase", "any": ["concentration"], "all": [], "marks": 1}, {"text": "The pH (using a buffer)", "any": ["ph", "buffer"], "all": [], "marks": 1}]'::jsonb, 'Independent: temperature [1]; dependent: the time until the starch is digested (iodine stays orange-brown) [1]; controls: the volume of starch and amylase [1], the concentration of starch and amylase [1], and the pH (using a buffer) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
