insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('21ae72a4-9136-5539-be35-afce1c6ade53', 'Put test tubes of starch and of amylase in a water bath at each temperature for 5 minutes [1]; mix them and put a drop of the mixture into iodine on a spotting tile [1] every 30 s, timing with a stopwatch until the iodine stays orange-brown [1]; measure the volumes with a syringe and use the same buffer [1]; repeat three times at each temperature and calculate a mean [1].', 'Put test tubes of starch and of amylase in a water bath at each temperature for 5 minutes [1]; mix them and put a drop of the mixture into iodine on a spotting tile [1] every 30 s, timing with a stopwatch until the iodine stays orange-brown [1]; measure the volumes with a syringe and use the same buffer [1]; repeat three times at each temperature and calculate a mean [1].', '[{"text": "Put test tubes of starch and of amylase in a water bath at each temperature for 5 minutes", "any": ["water bath"], "all": [], "marks": 1}, {"text": "Mix them and put a drop of the mixture into iodine on a spotting tile", "any": ["iodine", "spotting tile"], "all": [], "marks": 1}, {"text": "Every 30 s, timing with a stopwatch until the iodine stays orange-brown", "any": ["every 30", "samples", "stopwatch", "timer"], "all": [], "marks": 1}, {"text": "Measure the volumes with a syringe and use the same buffer", "any": ["measuring cylinder", "syringe", "pipette", "same volume"], "all": [], "marks": 1}, {"text": "Repeat three times at each temperature and calculate a mean", "any": ["repeat", "three times", "mean"], "all": [], "marks": 1}]'::jsonb, 'Put test tubes of starch and of amylase in a water bath at each temperature for 5 minutes [1]; mix them and put a drop of the mixture into iodine on a spotting tile [1] every 30 s, timing with a stopwatch until the iodine stays orange-brown [1]; measure the volumes with a syringe and use the same buffer [1]; repeat three times at each temperature and calculate a mean [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
