insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('544e6139-0557-5ee5-a6b1-986337bb1640', (select id from public.topics where id = '074d8b95-40b8-583a-9b76-9f324e19c12a'), 'short', 'Time for amylase to digest starch: 20 °C 280, 300, 290 s; 40 °C 60, 65, 55 s; 60 °C over 600 s (no digestion). Calculate the mean time at 20 °C and at 40 °C.', '[]'::jsonb, 2, 'Criterion C: Processing and evaluating', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('544e6139-0557-5ee5-a6b1-986337bb1640', 'Mean at 20 °C = (280 + 300 + 290) ÷ 3 = 290 s [1]; mean at 40 °C = (60 + 65 + 55) ÷ 3 = 60 s [1].', 'Mean at 20 °C = (280 + 300 + 290) ÷ 3 = 290 s [1]; mean at 40 °C = (60 + 65 + 55) ÷ 3 = 60 s [1].', '[{"text": "Mean at 20 °C = (280 + 300 + 290) ÷ 3 = 290 s", "any": ["3 290", "mean is 290", "mean of 290", "mean 290", "is 290"], "all": [], "marks": 1}, {"text": "Mean at 40 °C = (60 + 65 + 55) ÷ 3 = 60 s", "any": ["3 60", "mean is 60", "mean of 60", "mean 60", "is 60"], "all": [], "marks": 1}]'::jsonb, 'Mean at 20 °C = (280 + 300 + 290) ÷ 3 = 290 s [1]; mean at 40 °C = (60 + 65 + 55) ÷ 3 = 60 s [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
