insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('925a8901-e0cf-5780-acc7-6cfb2574a3b1', (select id from public.topics where id = '074d8b95-40b8-583a-9b76-9f324e19c12a'), 'short', 'Calculate the rate of reaction at 40 °C as 1/time, with units.', '[]'::jsonb, 2, 'Criterion C: Processing and evaluating', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('925a8901-e0cf-5780-acc7-6cfb2574a3b1', 'Rate = 1 ÷ 60 = 0.017 [1] s⁻¹ (per second) [1].', 'Rate = 1 ÷ 60 = 0.017 [1] s⁻¹ (per second) [1].', '[{"text": "Rate = 1 ÷ 60 = 0.017", "any": ["0.017", "0.0167", "1/60", "1 ÷ 60"], "all": [], "marks": 1}, {"text": "S⁻¹ (per second)", "any": ["s-1", "s⁻¹", "per second", "/s"], "all": [], "marks": 1}]'::jsonb, 'Rate = 1 ÷ 60 = 0.017 [1] s⁻¹ (per second) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
