insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('1beeed3f-faa1-5ad1-89d8-8c8d75e3aa3d', 'Between 20 and 40 °C the starch was digested faster (290 s to 60 s) [1]; at 60 °C it was not digested at all [1]; as temperature rises, molecules have more kinetic energy and collide more, up to the optimum [1]; at 60 °C the amylase was denatured, so its active site no longer fitted starch [1].', 'Between 20 and 40 °C the starch was digested faster (290 s to 60 s) [1]; at 60 °C it was not digested at all [1]; as temperature rises, molecules have more kinetic energy and collide more, up to the optimum [1]; at 60 °C the amylase was denatured, so its active site no longer fitted starch [1].', '[{"text": "Between 20 and 40 °C the starch was digested faster (290 s to 60 s)", "any": ["faster", "shorter time", "decrease", "quicker"], "all": [], "marks": 1}, {"text": "At 60 °C it was not digested at all", "any": ["60", "no digestion", "stopped", "did not"], "all": [], "marks": 1}, {"text": "As temperature rises, molecules have more kinetic energy and collide more, up to the optimum", "any": ["kinetic", "collisions", "optimum"], "all": [], "marks": 1}, {"text": "At 60 °C the amylase was denatured, so its active site no longer fitted starch", "any": ["denatur", "active site"], "all": [], "marks": 1}]'::jsonb, 'Between 20 and 40 °C the starch was digested faster (290 s to 60 s) [1]; at 60 °C it was not digested at all [1]; as temperature rises, molecules have more kinetic energy and collide more, up to the optimum [1]; at 60 °C the amylase was denatured, so its active site no longer fitted starch [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
