insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('7295174a-a58d-5dd6-a8b9-92959a76d00b', 'The three results (55–65 s) are close together, with a range of only 10 s [1], so they are reliable and repeatable [1].', 'The three results (55–65 s) are close together, with a range of only 10 s [1], so they are reliable and repeatable [1].', '[{"text": "The three results (55–65 s) are close together, with a range of only 10 s", "any": ["close", "similar", "small range", "consistent", "range"], "all": [], "marks": 1}, {"text": "They are reliable and repeatable", "any": ["reliable", "10", "repeatable"], "all": [], "marks": 1}]'::jsonb, 'The three results (55–65 s) are close together, with a range of only 10 s [1], so they are reliable and repeatable [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
