insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('2bf0069a-8087-53f1-97a8-cabcce5c369f', 'Only three temperatures were tested, so the optimum cannot be found exactly [1]; test more temperatures at 5 °C intervals between 30 and 50 °C [1]; judging when the iodine stops turning blue-black is subjective and samples were only taken every 30 s [1]; use a colour chart or colorimeter and sample every 10 s [1].', 'Only three temperatures were tested, so the optimum cannot be found exactly [1]; test more temperatures at 5 °C intervals between 30 and 50 °C [1]; judging when the iodine stops turning blue-black is subjective and samples were only taken every 30 s [1]; use a colour chart or colorimeter and sample every 10 s [1].', '[{"text": "Only three temperatures were tested, so the optimum cannot be found exactly", "any": ["only 3", "few temperatures", "gaps", "large intervals", "20 °c steps", "only three temperatures"], "all": [], "marks": 1}, {"text": "Test more temperatures at 5 °C intervals between 30 and 50 °C", "any": ["more temperatures", "35", "45", "smaller intervals", "5 °c"], "all": [], "marks": 1}, {"text": "Judging when the iodine stops turning blue-black is subjective and samples were only taken every 30 s", "any": ["iodine", "colour", "judge", "subjective", "end point", "30 s"], "all": [], "marks": 1}, {"text": "Use a colour chart or colorimeter and sample every 10 s", "any": ["colorimeter", "colour chart", "same person", "every 10", "shorter intervals"], "all": [], "marks": 1}]'::jsonb, 'Only three temperatures were tested, so the optimum cannot be found exactly [1]; test more temperatures at 5 °C intervals between 30 and 50 °C [1]; judging when the iodine stops turning blue-black is subjective and samples were only taken every 30 s [1]; use a colour chart or colorimeter and sample every 10 s [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
