insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('6827f5ba-8ec8-5064-b90b-17c0937427a4', (select id from public.topics where id = '074d8b95-40b8-583a-9b76-9f324e19c12a'), 'short', 'Pulse rates (beats per minute) of a student: rest 70; after 2 minutes of skipping 140; 2 minutes after stopping 98; 5 minutes after stopping 72. Calculate the percentage increase after skipping and the recovery time.', '[]'::jsonb, 3, 'Criterion C: Processing and evaluating', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('6827f5ba-8ec8-5064-b90b-17c0937427a4', 'Increase = (140 − 70) ÷ 70 × 100 = 100% [1]; the pulse returned to near resting (72) after about 5 [1] minutes [1].', 'Increase = (140 − 70) ÷ 70 × 100 = 100% [1]; the pulse returned to near resting (72) after about 5 [1] minutes [1].', '[{"text": "Increase = (140 − 70) ÷ 70 × 100 = 100%", "any": ["100"], "all": [], "marks": 1}, {"text": "The pulse returned to near resting (72) after about 5", "any": ["5", "five"], "all": [], "marks": 1}, {"text": "Minutes", "any": ["minutes", "min"], "all": [], "marks": 1}]'::jsonb, 'Increase = (140 − 70) ÷ 70 × 100 = 100% [1]; the pulse returned to near resting (72) after about 5 [1] minutes [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
