insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('c92323db-39c7-5f55-a854-91fb0719a61a', (select id from public.topics where id = '074d8b95-40b8-583a-9b76-9f324e19c12a'), 'short', 'Explain the changes in pulse rate using your knowledge of respiration and the cardiovascular system.', '[]'::jsonb, 3, 'Criterion C: Processing and evaluating', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('c92323db-39c7-5f55-a854-91fb0719a61a', 'During skipping, muscles respire faster [1], needing more oxygen and glucose and producing more carbon dioxide [1]; the heart pumps faster to deliver and remove these, and stays raised afterwards to repay the oxygen debt (break down lactic acid) [1].', 'During skipping, muscles respire faster [1], needing more oxygen and glucose and producing more carbon dioxide [1]; the heart pumps faster to deliver and remove these, and stays raised afterwards to repay the oxygen debt (break down lactic acid) [1].', '[{"text": "During skipping, muscles respire faster", "any": ["respir", "muscles"], "all": [], "marks": 1}, {"text": "Needing more oxygen and glucose and producing more carbon dioxide", "any": ["oxygen", "glucose", "carbon dioxide"], "all": [], "marks": 1}, {"text": "The heart pumps faster to deliver and remove these, and stays raised afterwards to repay the oxygen debt (break down lactic acid)", "any": ["heart", "pump", "oxygen debt", "lactic acid"], "all": [], "marks": 1}]'::jsonb, 'During skipping, muscles respire faster [1], needing more oxygen and glucose and producing more carbon dioxide [1]; the heart pumps faster to deliver and remove these, and stays raised afterwards to repay the oxygen debt (break down lactic acid) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
