insert into public.quizzes (id, topic_id, title, instructions, time_limit_minutes, max_attempts, published, show_results, category, feedback_mode, created_by, subject) values ('e3f94c49-027c-58af-8b81-8747063f431b', (select id from public.topics where id = '074d8b95-40b8-583a-9b76-9f324e19c12a'), 'Grade 9 · Biology · Digestion, enzymes, circulation and respiration · Criterion D test: Reflecting on the impacts of science', 'MYP 4 (Grade 9) Biology end-of-unit test. Statement of inquiry: evidence of healthy wellbeing is a consequence of the proper functioning of systems. Section 1: Criterion D: Reflecting on the impacts of science. Answer every question, using the command terms. Written answers are marked against the mark scheme; your teacher checks every mark. 19 marks, 40 minutes.', 40, 1, true, true, 'exam', 'hybrid', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e', 'Biology') on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, time_limit_minutes = excluded.time_limit_minutes, category = 'exam', subject = excluded.subject, topic_id = excluded.topic_id;
insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('44431a5e-fad3-5d6a-8a4f-9dc1f3d0be25', (select id from public.topics where id = '074d8b95-40b8-583a-9b76-9f324e19c12a'), 'short', 'Lactose-free milk is more expensive than normal milk. Discuss the benefits and limitations of lactose-free milk for Kenyan families.', '[]'::jsonb, 4, 'Criterion D: Reflecting on the impacts of science', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('44431a5e-fad3-5d6a-8a4f-9dc1f3d0be25', 'Lactose-free milk lets lactose-intolerant people drink milk without cramps or diarrhoea [1], so they still get calcium and protein for strong bones [1]; but it costs more and may not be sold in rural shops, so poor families cannot afford it [1]; overall it is useful, but fermented milk such as mala or yoghurt (with less lactose) is a cheaper alternative [1].', 'Lactose-free milk lets lactose-intolerant people drink milk without cramps or diarrhoea [1], so they still get calcium and protein for strong bones [1]; but it costs more and may not be sold in rural shops, so poor families cannot afford it [1]; overall it is useful, but fermented milk such as mala or yoghurt (with less lactose) is a cheaper alternative [1].', '[{"text": "Lactose-free milk lets lactose-intolerant people drink milk without cramps or diarrhoea", "any": ["lactose intoleran", "cramps", "diarrhoea", "symptoms"], "all": [], "marks": 1}, {"text": "They still get calcium and protein for strong bones", "any": ["calcium", "protein", "nutrients", "children", "bones"], "all": [], "marks": 1}, {"text": "It costs more and may not be sold in rural shops, so poor families cannot afford it", "any": ["cost", "expensive", "afford", "rural", "available"], "all": [], "marks": 1}, {"text": "Overall it is useful, but fermented milk such as mala or yoghurt (with less lactose) is a cheaper alternative", "any": ["i think", "overall", "conclusion", "yoghurt", "mala", "alternative"], "all": [], "marks": 1}]'::jsonb, 'Lactose-free milk lets lactose-intolerant people drink milk without cramps or diarrhoea [1], so they still get calcium and protein for strong bones [1]; but it costs more and may not be sold in rural shops, so poor families cannot afford it [1]; overall it is useful, but fermented milk such as mala or yoghurt (with less lactose) is a cheaper alternative [1].') on