insert into public.quiz_questions (quiz_id, question_id, position) values ('e3f94c49-027c-58af-8b81-8747063f431b', '44431a5e-fad3-5d6a-8a4f-9dc1f3d0be25', 1);
insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('be3b6f26-81ad-53f6-9c86-220922eefe60', (select id from public.topics where id = '074d8b95-40b8-583a-9b76-9f324e19c12a'), 'short', 'Explain how aflatoxin in stored maize affects health, and evaluate one solution for farmers.', '[]'::jsonb, 4, 'Criterion D: Reflecting on the impacts of science', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('be3b6f26-81ad-53f6-9c86-220922eefe60', 'Aflatoxin is a poison that damages the liver and can cause liver cancer [1]; it is made by moulds growing on damp, badly stored maize [1]; drying maize well and storing it in hermetic bags prevents mould growth [1]; this works well but the bags cost money and farmers need training, so government support would help [1].', 'Aflatoxin is a poison that damages the liver and can cause liver cancer [1]; it is made by moulds growing on damp, badly stored maize [1]; drying maize well and storing it in hermetic bags prevents mould growth [1]; this works well but the bags cost money and farmers need training, so government support would help [1].', '[{"text": "Aflatoxin is a poison that damages the liver and can cause liver cancer", "any": ["liver", "cancer", "poison", "toxin"], "all": [], "marks": 1}, {"text": "It is made by moulds growing on damp, badly stored maize", "any": ["mould", "damp", "storage", "fungus"], "all": [], "marks": 1}, {"text": "Drying maize well and storing it in hermetic bags prevents mould growth", "any": ["dry", "hermetic", "bags", "test", "sort"], "all": [], "marks": 1}, {"text": "This works well but the bags cost money and farmers need training, so government support would help", "any": ["cost", "afford", "training", "electricity", "effective", "difficult"], "all": [], "marks": 1}]'::jsonb, 'Aflatoxin is a poison that damages the liver and can cause liver cancer [1]; it is made by moulds growing on damp, badly stored maize [1]; drying maize well and storing it in hermetic bags prevents mould growth [1]; this works well but the bags cost money and farmers need training, so government support would help [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e3f94c49-027c-58af-8b81-8747063f431b', 'be3b6f26-81ad-53f6-9c86-220922eefe60', 2);
insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('6f13bc15-163a-512c-8a1f-59163838fd86', (select id from public.topics where id = '074d8b95-40b8-583a-9b76-9f324e19c12a'), 'short', 'Discuss whether the Kenyan government should tax sugary drinks to reduce type 2 diabetes. Consider economic, social and health factors.', '[]'::jsonb, 4, 'Criterion D: Reflecting on the impacts of science', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('6f13bc15-163a-512c-8a1f-59163838fd86', 'Health: a tax raises prices so people drink less sugar, reducing obesity and type 2 diabetes [1]; economic: it raises money for health care, but drink companies and shopkeepers may lose income and jobs [1]; social: it takes more money from poor families and limits personal choice [1]; overall I think the tax is justified if the money is used for diabetes care and clean drinking water [1].', 'Health: a tax raises prices so people drink less sugar, reducing obesity and type 2 diabetes [1]; economic: it raises money for health care, but drink companies and shopkeepers may lose income and jobs [1]; social: it takes more money from poor families and limits personal choice [1]; overall I think the tax is justified if the money is used for diabetes care and clean drinking water [1].', '[{"text": "Health: a tax raises prices so people drink less sugar, reducing obesity and type 2 diabetes", "any": ["obesity", "sugar intake", "less sugar", "drink less"], "all": [], "marks": 1}, {"text": "Economic: it raises money for health care, but drink companies and shopkeepers may lose income and jobs", "any": ["revenue", "jobs", "business", "income", "raises money"], "all": [], "marks": 1}, {"text": "Social: it takes more money from poor families and limits personal choice", "any": ["poor", "choice", "culture", "fair"], "all": [], "marks": 1}, {"text": "Overall I think the tax is justified if the money is used for diabetes care and clean drinking water", "any": ["i think", "overall", "conclusion", "should", "because"], "all": [], "marks": 1}]'::jsonb, 'Health: a tax raises prices so people drink less sugar, reducing obesity and type 2 diabetes [1]; economic: it raises money for health care, but drink companies and shopkeepers may lose income and jobs [1]; social: it takes more money from poor families and limits personal choice [1]; overall I think the tax is justified if the money is used for diabetes care and clean drinking water [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e3f94c49-027c-58af-8b81-8747063f431b', '6f13bc15-163a-512c-8a1f-59163838fd86', 3);
insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('5c5cec7a-c4ab-52b4-a066-c3d996e8f380', (select id from public.topics where id = '074d8b95-40b8-583a-9b76-9f324e19c12a'), 'short', 'Some parents refuse vaccination because of rumours on social media. Evaluate how scientific information about vaccines could be communicated better in your community.', '[]'::jsonb, 4, 'Criterion D: Reflecting on the impacts of science', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('5c5cec7a-c4ab-52b4-a066-c3d996e8f380', 'Information could be shared through community health volunteers, radio in local languages and religious leaders [1], whom people trust, using clear evidence such as how measles deaths fell after vaccination [1]; however, rumours spread faster than facts and some people fear medicine [1]; overall I think trusted local voices answering questions face to face work best [1].', 'Information could be shared through community health volunteers, radio in local languages and religious leaders [1], whom people trust, using clear evidence such as how measles deaths fell after vaccination [1]; however, rumours spread faster than facts and some people fear medicine [1]; overall I think trusted local voices answering questions face to face work best [1].', '[{"text": "Information could be shared through community health volunteers, radio in local languages and religious leaders", "any": ["social media", "radio", "chiefs", "religious leaders", "community health", "school", "local language"], "all": [], "marks": 1}, {"text": "Whom people trust, using clear evidence such as how measles deaths fell after vaccination", "any": ["trust", "evidence", "data", "stories", "doctors"], "all": [], "marks": 1}, {"text": "However, rumours spread faster than facts and some people fear medicine", "any": ["difficult", "rumour", "misinformation", "fear", "distance", "cost"], "all": [], "marks": 1}, {"text": "Overall I think trusted local voices answering questions face to face work best", "any": ["i think", "overall", "conclusion", "best", "because"], "all": [], "marks": 1}]'::jsonb, 'Information could be shared through community health volunteers, radio in local languages and religious leaders [1], whom people trust, using clear evidence such as how measles deaths fell after vaccination [1]; however, rumours spread faster than facts and some people fear medicine [1]; overall I think trusted local voices answering questions face to face work best [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
