insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('07e59a0f-5ce2-52c8-8d11-230b332b34f5', (select id from public.topics where id = '074d8b95-40b8-583a-9b76-9f324e19c12a'), 'short', 'Explain why blood donation is important to society and suggest one ethical issue linked to it.', '[]'::jsonb, 3, 'Criterion D: Reflecting on the impacts of science', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('07e59a0f-5ce2-52c8-8d11-230b332b34f5', 'Donated blood saves the lives of accident victims, mothers after childbirth and children with anaemia [1]; Kenya has a shortage, so regular donors are needed [1]; an ethical issue is whether donors should be paid, which might attract people who hide infections [1].', 'Donated blood saves the lives of accident victims, mothers after childbirth and children with anaemia [1]; Kenya has a shortage, so regular donors are needed [1]; an ethical issue is whether donors should be paid, which might attract people who hide infections [1].', '[{"text": "Donated blood saves the lives of accident victims, mothers after childbirth and children with anaemia", "any": ["save", "accident", "surgery", "mothers", "anaemia", "lives"], "all": [], "marks": 1}, {"text": "Kenya has a shortage, so regular donors are needed", "any": ["shortage", "need", "supply"], "all": [], "marks": 1}, {"text": "An ethical issue is whether donors should be paid, which might attract people who hide infections", "any": ["consent", "paid", "money", "safety", "tested", "religion", "privacy", "fair"], "all": [], "marks": 1}]'::jsonb, 'Donated blood saves the lives of accident victims, mothers after childbirth and children with anaemia [1]; Kenya has a shortage, so regular donors are needed [1]; an ethical issue is whether donors should be paid, which might attract people who hide infections [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
